package main

import (
	"fmt"
	"strings"
)

func WordCount(s string) map[string]int {
	counts := map[string]int{}
	for _, w := range strings.Fields(s) {
		counts[w]++
	}
	return counts
}

func main() {
	fmt.Println(WordCount("go is fun and go is fast"))
}
